/// <summary>
/// update field values to record after mapping to the entity.
/// </summary>
/// <param name="_sender"><c>InventInventoryCountingJournalLineEntity</c> raising the event.</param>
/// <param name="_eventArgs">The arguments of this event.</param>
[DataEventHandler(tableStr(InventInventoryCountingJournalLineEntity), DataEventType::MappedEntityToDataSource)]
public static void InventInventoryCountingJournalLineEntity_onMappedEntityToDataSource(Common _sender, DataEventArgs _eventArgs)
{
    DataEntityContextEventArgs contextEventArgs = _eventArgs as DataEntityContextEventArgs;
    DataEntityRuntimeContext entityCtx = contextEventArgs.parmEntityContext();
    DataEntityDataSourceRuntimeContext dataSourceCtx = contextEventArgs.parmEntityDataSourceContext();

    if ((entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert || entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
         && dataSourceCtx.name() == dataEntityDataSourceStr(InventInventoryCountingJournalLineEntity, InventJournalTrans))
    {
        InventInventoryCountingJournalLineEntity inventInventoryCountingJournalEntry = _sender as InventInventoryCountingJournalLineEntity;
        InventJournalTrans inventJournalTrans = dataSourceCtx.getBuffer();

        if (InventJournalName::find(inventInventoryCountingJournalEntry.JournalNumber).METExternalWMSUOM 
            && InventJournalTable::find(inventInventoryCountingJournalEntry.JournalNumber).METJournalLinesCount)
        {
            if (inventInventoryCountingJournalEntry.CountedCatchWeightQuantity)
            {
                inventInventoryCountingJournalEntry.CountedCatchWeightQuantity = METJournalUnitConversion::construct().getConvertedQtyCWQtyForItem(InventLocation::find         (inventInventoryCountingJournalEntry.WarehouseId), inventInventoryCountingJournalEntry.ItemNumber, inventInventoryCountingJournalEntry.CountedCatchWeightQuantity);

                inventJournalTrans.PdsCWQty = inventInventoryCountingJournalEntry.CountedCatchWeightQuantity;
                inventJournalTrans.modifiedField(fieldNum(InventJournalTrans, PdsCWQty));
            }
            else
            {

                inventInventoryCountingJournalEntry.CountedQuantity = METJournalUnitConversion::construct().getConvertedQtyCWQtyForItem(InventLocation::find(inventInventoryCountingJournalEntry.WarehouseId), inventInventoryCountingJournalEntry.ItemNumber, inventInventoryCountingJournalEntry.CountedQuantity);

                inventJournalTrans.Qty = inventInventoryCountingJournalEntry.CountedQuantity;
            }
        }
    }
}
